<template><section v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane v-if="canManage" label="流程管理" name="definitions"><div class="tools"><el-input v-model="search" placeholder="搜索流程名称或分组" clearable/><el-button @click="$emit('builtin','store-report')">问题类型与申报流程</el-button><el-button type="primary" @click="edit()">新建流程</el-button></div><el-table :data="filtered"><el-table-column label="流程" min-width="220"><template #default="{row}"><b>{{row.name}}</b><div class="secondary">{{row.category}}</div></template></el-table-column><el-table-column label="表单" width="110"><template #default="{row}">{{row.draft.fields.length}} 个字段</template></el-table-column><el-table-column label="状态" min-width="180"><template #default="{row}"><el-tag :type="row.status==='published'?'success':'info'">{{{draft:'草稿',published:'已发布',disabled:'已停用'}[row.status]}}</el-tag><span class="secondary"> v{{row.version}}</span><div v-if="row.status==='published'&&JSON.stringify(row.draft)!==JSON.stringify(row.published)" class="secondary">有未发布修改</div></template></el-table-column><el-table-column label="审批结束" min-width="150"><template #default="{row}">{{row.draft.execution==='archive'?'审批后归档':'待人事执行'}}</template></el-table-column><el-table-column label="操作" min-width="320"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link @click="copy(row)">复制</el-button><el-button link type="primary" @click="publish(row)">发布</el-button><el-button link @click="history(row)">版本</el-button><el-button v-if="row.status==='published'" link type="danger" @click="disable(row)">停用</el-button></template></el-table-column></el-table><el-empty v-if="!filtered.length" description="还没有自建流程，从新建流程开始"/><div class="builtins"><h3>已接入业务</h3><p>这些业务带有专属执行校验，保留现有记录和配置。普通审批请直接新建流程。</p><el-button v-for="b in builtins" :key="b.value" @click="$emit('builtin',b.value)">{{b.label}}</el-button></div></el-tab-pane><el-tab-pane label="申请与审批" name="requests"><div class="tools"><el-select v-model="filter" aria-label="筛选申请"><el-option label="全部申请" value="all"/><el-option label="待我审批" value="mine"/><el-option label="我发起的" value="created"/></el-select><el-button type="primary" @click="openStart">发起申请</el-button><el-button @click="load">刷新</el-button></div><el-table :data="filteredRequests"><el-table-column prop="title" label="流程" min-width="200"/><el-table-column prop="store_name" label="门店" min-width="160"/><el-table-column prop="created_name" label="申请人" width="120"/><el-table-column label="进度" min-width="200"><template #default="{row}">{{status(row)}}<div class="secondary">发布版本 v{{row.version}}</div></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="detail=row;note=''">查看申请</el-button></template></el-table-column></el-table><el-empty v-if="!filteredRequests.length" description="暂无申请"/></el-tab-pane></el-tabs>
<el-drawer v-model="editing" title="流程设计" size="min(1000px,96vw)" :close-on-click-modal="false"><el-steps :active="step" finish-status="success" simple><el-step title="基本信息"/><el-step title="申请表单"/><el-step title="审批与结束"/></el-steps><el-form label-position="top" class="designer"><template v-if="step===0"><div class="two"><el-form-item label="流程名称" required><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="分组" required><el-input v-model="form.category" placeholder="如：人事、门店运营、费用" maxlength="40"/></el-form-item></div><el-form-item label="流程用途"><el-select v-model="form.purpose" @change="form.purpose==='employee-profile-change'&&(form.execution='manual')"><el-option value="general" label="通用审批"/><el-option value="employee-profile-change" label="员工本人资料更正"/></el-select></el-form-item><el-form-item label="用途说明"><el-input v-model="form.description" type="textarea" maxlength="1000"/></el-form-item><p>发起岗位还需在对应使用端勾选“发起自定义流程申请”权限。</p><el-form-item label="允许发起的岗位" required><el-select v-model="form.initiator_ids" multiple filterable><el-option v-for="p in data.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-form-item label="适用门店"><el-radio-group v-model="form.mode"><el-radio-button value="all">全部门店</el-radio-button><el-radio-button value="stores">指定门店</el-radio-button><el-radio-button value="regions">指定区域</el-radio-button></el-radio-group><StoreRegionSelect v-if="form.mode==='stores'" v-model="form.store_ids" :stores="data.stores" multiple input-width="100%"/><el-select v-if="form.mode==='regions'" v-model="form.region_ids" multiple filterable><el-option v-for="r in data.regions" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item></template><template v-else-if="step===1"><p>按手机填写顺序添加字段；申请门店由系统单独选择，不必重复添加。</p><div v-for="(f,i) in form.fields" :key="f.id" class="block"><div class="block-head"><b>字段 {{i+1}}</b><div><el-button link :disabled="!i" @click="move(form.fields,i,-1)">上移</el-button><el-button link :disabled="i===form.fields.length-1" @click="move(form.fields,i,1)">下移</el-button><el-button link type="danger" @click="removeField(f,i)">移除</el-button></div></div><div class="two"><el-form-item label="字段名称"><el-input v-model="f.label" maxlength="60"/></el-form-item><el-form-item label="字段类型"><el-select v-model="f.type"><el-option v-for="(label,type) in types" :key="type" :label="label" :value="type"/></el-select></el-form-item></div><el-checkbox v-model="f.required">必填</el-checkbox><el-form-item v-if="f.type==='select'" label="选项（每行一个）"><el-input :model-value="f.options.join('\n')" type="textarea" @update:model-value="f.options=$event.split('\n')"/></el-form-item></div><el-button :disabled="form.fields.length>=30" @click="form.fields.push({id:'f_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),label:'',type:'text',required:true,options:[]})">添加字段</el-button><h3>表单预览</h3><WorkflowFormFields :fields="form.fields" v-model="preview" :stores="data.stores" :employees="data.employees"/></template><template v-else><div v-for="(n,i) in form.nodes" :key="i" class="block"><div class="block-head"><b>节点 {{i+1}}</b><div><el-button link :disabled="!i" @click="move(form.nodes,i,-1)">上移</el-button><el-button link :disabled="i===form.nodes.length-1" @click="move(form.nodes,i,1)">下移</el-button><el-button link type="danger" :disabled="form.nodes.length===1" @click="form.nodes.splice(i,1)">移除</el-button></div></div><el-form-item label="节点名称"><el-input v-model="n.name"/></el-form-item><div class="two"><el-select v-model="n.kind" aria-label="审批人匹配方式" @change="n.ids=[]"><el-option value="positions" label="按负责门店的岗位"/><el-option value="users" label="指定人员"/></el-select><el-select v-model="n.mode" aria-label="审批通过方式"><el-option value="any" label="任一人同意"/><el-option value="all" label="所有人同意"/></el-select></div><el-select v-model="n.ids" multiple filterable placeholder="选择审批岗位或人员"><el-option v-for="p in n.kind==='users'?data.users:data.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select><div class="condition"><span>进入条件：{{n.when.length?'以下条件全部成立':'无条件进入'}}</span><div v-for="(w,wi) in n.when" :key="wi" class="condition-row"><el-select v-model="w.field" aria-label="条件字段"><el-option v-for="f in form.fields.filter(f=>['text','select','number'].includes(f.type))" :key="f.id" :value="f.id" :label="f.label"/></el-select><el-select v-model="w.op" aria-label="条件比较"><el-option value="eq" label="等于"/><el-option value="ne" label="不等于"/><el-option v-if="form.fields.find(f=>f.id===w.field)?.type==='number'" value="gte" label="大于等于"/><el-option v-if="form.fields.find(f=>f.id===w.field)?.type==='number'" value="lte" label="小于等于"/></el-select><el-input v-model="w.value" aria-label="条件值"/><el-button link type="danger" @click="n.when.splice(wi,1)">移除</el-button></div><el-button link :disabled="n.when.length>=5" @click="n.when.push({field:'',op:'eq',value:''})">添加条件</el-button></div></div><el-button :disabled="form.nodes.length>=8" @click="form.nodes.push(node())">添加审批节点</el-button><p>发起人不能审批自己的申请。条件不匹配会跳过该节点；没有节点或没有有效审批人时阻止提交。</p><el-form-item label="系统抄送"><div class="two"><el-select v-model="form.cc.kind" @change="form.cc.ids=[]"><el-option value="users" label="指定人员"/><el-option value="positions" label="按负责门店的岗位"/></el-select><el-select v-model="form.cc.ids" multiple filterable><el-option v-for="p in form.cc.kind==='users'?data.users:data.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select></div></el-form-item><el-form-item label="全部审批通过后"><el-radio-group v-model="form.execution"><el-radio value="archive" :disabled="form.purpose==='employee-profile-change'">自动归档</el-radio><el-radio value="manual">交人事确认执行并填写结果</el-radio></el-radio-group></el-form-item><el-alert title="通用流程不会自动调岗或修改业务数据。此类动作请使用已接入业务的专用流程。" :closable="false"/></template></el-form><template #footer><div class="footer"><el-button @click="editing=false">取消</el-button><el-button :disabled="step===0" @click="step--">上一步</el-button><el-button v-if="step<2" type="primary" @click="step++">下一步</el-button><el-button v-else type="primary" :loading="busy" @click="save">保存草稿</el-button></div></template></el-drawer>
<el-dialog v-model="starting" title="发起流程申请" width="min(700px,96vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="流程"><el-select v-model="application.definition_id" @change="application.values={};application.store_id=null"><el-option v-for="d in options.definitions" :key="d.id" :label="d.name+' · v'+d.version" :value="d.id"/></el-select></el-form-item><el-form-item label="申请门店"><StoreRegionSelect v-model="application.store_id" @change="application.values={}" :stores="options.stores.filter(s=>selected?.store_ids.includes(s.id))" restrict-to-stores /></el-form-item></el-form><p v-if="selected">{{selected.form.description}}</p><WorkflowFormFields v-if="selected" :key="application.definition_id+'-'+application.store_id" :fields="selected.form.fields" v-model="application.values" :stores="options.stores" :employees="options.employees.filter(e=>selected.form.purpose!=='employee-profile-change'||e.id===options.self_employee_id)" :definition-id="selected.id" :store-id="application.store_id" @uploading="uploading=$event"/><template #footer><el-button @click="starting=false">取消</el-button><el-button type="primary" :disabled="uploading||!application.store_id" :loading="busy" @click="submit">提交审批</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" title="申请详情" size="min(700px,96vw)" @close="detail=null"><template v-if="detail"><h2>{{detail.title}}</h2><p>{{detail.store_name}} · {{detail.created_name}} · v{{detail.version}}</p><el-alert :title="status(detail)" :closable="false"/><WorkflowFormFields :fields="detail.fields" :model-value="detail.values" readonly :files="detail.files" :value-labels="detail.value_labels" :stores="data.stores" :employees="data.employees"/><h3>审批顺序</h3><p v-for="(n,i) in detail.nodes" :key="i">{{i+1}}. {{n.name}} · {{n.mode==='all'?'会签':'任一人同意'}}</p><h3>处理记录</h3><el-timeline><el-timeline-item v-for="e in detail.events" :key="e.id" :timestamp="new Date(e.created_at).toLocaleString('zh-CN')">{{e.name}} · {{actions[e.action]||e.action}}<p>{{e.note}}</p></el-timeline-item></el-timeline><el-input v-if="detail.can_review||detail.can_execute" v-model="note" type="textarea" placeholder="审批意见／执行结果" maxlength="1000"/><div class="tools"><el-button v-if="detail.can_cancel" :disabled="busy" @click="act('cancel')">撤回申请</el-button><el-button v-if="detail.can_review" :disabled="busy" @click="act('reject')">驳回</el-button><el-button v-if="detail.can_review" type="primary" :disabled="busy" @click="act('approve')">同意</el-button><el-button v-if="detail.can_execute" type="primary" :disabled="busy" @click="act('execute')">确认已执行</el-button></div></template></el-drawer><el-dialog v-model="versionsOpen" title="发布版本" width="min(700px,96vw)"><div v-for="v in versions" :key="v.version" class="block"><b>v{{v.version}} · {{v.config.name}}</b><p>{{v.created_at}}</p><p>{{v.config.fields.map(f=>f.label).join('、')}}</p><p>{{v.config.nodes.map(n=>n.name).join(' → ')}}</p></div><el-empty v-if="!versions.length" description="尚未发布"/></el-dialog></section></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {useAuthStore} from '@/stores/auth';import {customWorkflowApi as api} from '@/api';import StoreRegionSelect from './StoreRegionSelect.vue';import WorkflowFormFields from './WorkflowFormFields.vue';
defineEmits(['builtin']);const auth=useAuthStore(),canManage=computed(()=>(auth.user?.position_permissions||[]).some(p=>p==='*'||p==='workflow.manage'));const tab=ref(canManage.value?'definitions':'requests'),loading=ref(false),busy=ref(false),error=ref(''),search=ref(''),filter=ref('all'),data=ref({definitions:[],positions:[],users:[],stores:[],regions:[],employees:[]}),rows=ref([]),editing=ref(false),form=ref({}),step=ref(0),preview=ref({}),starting=ref(false),application=ref({values:{}}),options=ref({definitions:[],stores:[],employees:[]}),uploading=ref(false),detail=ref(null),note=ref(''),versions=ref([]),versionsOpen=ref(false);const types={text:'单行文字',textarea:'多行文字',number:'数字',date:'日期',select:'单项选择',image:'图片',attachment:'附件',employee:'本店员工',store:'门店'};const builtins=[{value:'staff-mini-role',label:'门店岗位调整'},{value:'staff-reserve-transfer',label:'储备人员调动'},{value:'staff-manager-appointment',label:'正式店长任命'},{value:'store-report',label:'门店问题申报'}],actions={submit:'发起',approve:'同意',reject:'驳回',cancel:'撤回',execute:'执行完成'};const node=()=>({name:'审批',kind:'positions',ids:[],mode:'any',when:[]}),move=(a,i,d)=>{[a[i],a[i+d]]=[a[i+d],a[i]]};const filtered=computed(()=>data.value.definitions.filter(d=>(d.name+' '+d.category).includes(search.value))),selected=computed(()=>options.value.definitions.find(d=>d.id===application.value.definition_id)),filteredRequests=computed(()=>rows.value.filter(r=>filter.value==='all'||filter.value==='mine'&&r.can_review||filter.value==='created'&&r.created_by===auth.user?.id));const status=r=>r.status==='pending'?'待'+r.stage_name:r.status==='approved'?(r.execution_status==='done'?'已完成归档':'已通过 · 待执行'):r.status==='rejected'?'已驳回':'已撤回';
async function load(){loading.value=true;error.value='';try{if(canManage.value)data.value=await api.definitions();rows.value=(await api.requests()).rows}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(d){form.value=d?JSON.parse(JSON.stringify({...d.draft,id:d.id,revision:d.revision})):{name:'',purpose:'general',category:'通用审批',description:'',mode:'all',store_ids:[],region_ids:[],initiator_ids:[],fields:[],nodes:[node()],cc:{kind:'users',ids:[]},execution:'archive'};step.value=0;preview.value={};editing.value=true}
function copy(d){edit(d);delete form.value.id;delete form.value.revision;form.value.name+='（副本）'}
function removeField(f,i){if(form.value.nodes.some(n=>n.when.some(w=>w.field===f.id)))return ElMessage.error('此字段被节点条件引用，请先移除条件');form.value.fields.splice(i,1)}
async function run(fn){if(busy.value)return;busy.value=true;try{await fn()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}finally{busy.value=false}}
const save=()=>run(async()=>{await api.save(form.value);editing.value=false;await load();ElMessage.success('草稿已保存，发布后新申请才会使用')});
const publish=d=>run(async()=>{await ElMessageBox.confirm('发布后，新申请使用此版本；正在审批的申请保留原版本。','发布流程');await api.publish(d.id,{revision:d.revision});await load();ElMessage.success('已发布')});
const disable=d=>run(async()=>{await ElMessageBox.confirm('停用后不能再发起；已有申请继续办理。','停用流程');await api.disable(d.id,{revision:d.revision});await load()});
const history=d=>run(async()=>{versions.value=(await api.versions(d.id)).versions;versionsOpen.value=true});
async function openStart(){try{options.value=await api.options();if(!options.value.definitions.length)return ElMessage.info('当前岗位暂无可发起的已发布流程');application.value={definition_id:null,store_id:null,values:{}};starting.value=true}catch(e){ElMessage.error(e.message)}}
const submit=()=>run(async()=>{if(!selected.value)return;await api.start({...application.value,version:selected.value.version});starting.value=false;await load();ElMessage.success('申请已提交')});
const act=action=>run(async()=>{if(['reject','execute'].includes(action)&&!note.value.trim())throw new Error('请填写驳回原因／执行结果');await ElMessageBox.confirm('确认'+actions[action]+'？',actions[action]);detail.value=(await api.decision(detail.value.id,{action,revision:detail.value.revision,note:note.value})).record;note.value='';await load()});onMounted(load);
</script><style scoped>.tools{display:flex;gap:12px;align-items:center;margin:20px 0}.tools>.el-input,.tools>.el-select{max-width:320px}.secondary,p{font-size:13px;color:var(--el-text-color-secondary);line-height:1.7}.secondary{margin-top:5px}.builtins{margin-top:32px;padding-top:20px;border-top:1px solid var(--el-border-color-lighter)}.designer{margin-top:28px}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:12px 0}.el-select{width:100%}.block{border:1px solid var(--el-border-color-lighter);border-radius:12px;padding:20px;margin:20px 0;background:var(--el-fill-color-blank)}.block-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.condition{margin-top:20px;padding:14px;background:var(--el-fill-color-light);border-radius:8px;font-size:13px}.condition-row{display:grid;grid-template-columns:1.5fr 1fr 1fr auto;gap:8px;margin:10px 0}.footer{display:flex;justify-content:flex-end;gap:10px}.footer .el-button{margin:0}@media(max-width:640px){.two{grid-template-columns:1fr}.tools{flex-wrap:wrap}.condition-row{grid-template-columns:1fr 1fr}.builtins .el-button{margin:5px}}</style>
